package test.ts.javainterpreter.test;

/*Generated by MPS */

import org.junit.jupiter.api.Test;
import com.mbeddr.mpsutil.interpreter.rt.ComputationTrace;
import org.junit.Assert;

public class ComputationTraceTest_Test {
  @Test
  public void test_addChildRefusesAnAncestor() throws Exception {
    ComputationTrace root = new ComputationTrace();
    ComputationTrace child = new ComputationTrace();
    ComputationTrace grandChild = new ComputationTrace();
    root.addChild(child);
    child.addChild(grandChild);

    grandChild.addChild(root);

    Assert.assertNull("a root trace added below its own grandchild must keep no parent", root.getParent());
    Assert.assertNull("a grandchild must not take the root it is below as a child", grandChild.getFirstChild());
  }
  @Test
  public void test_addChildRefusesTheTraceItself() throws Exception {
    ComputationTrace trace = new ComputationTrace();

    trace.addChild(trace);

    Assert.assertNull("a trace added to itself must not become its own parent", trace.getParent());
    Assert.assertNull("a trace added to itself must not become its own child", trace.getFirstChild());
  }
  @Test
  public void test_deleteChildrenDetachesTheChildren() throws Exception {
    ComputationTrace parent = new ComputationTrace();
    ComputationTrace child = new ComputationTrace();
    parent.addChild(child);

    parent.deleteChildren();

    Assert.assertNull("deleteChildren must detach a deleted child from its parent", child.getParent());
    // addChild skips its cycle check for a trace without children, which the former parent now is
    child.addChild(parent);
    Assert.assertSame("the former parent added below its former child must have that child as its root, without a cycle", child, parent.rootTrace());
  }
  @Test
  public void test_deleteChildrenKeepsAChildThatMovedToAnotherParent() throws Exception {
    ComputationTrace first = new ComputationTrace();
    ComputationTrace second = new ComputationTrace();
    ComputationTrace child = new ComputationTrace();
    first.addChild(child);
    second.addChild(child);

    first.deleteChildren();

    Assert.assertSame("deleteChildren of a former parent must not detach a child from the parent it was added to since", second, child.getParent());
  }
}
